Let $E$ be a normed space, $N=\mathbb N$ (or any other directed set not containing a largest element), and $j_{nm} = \operatorname{id}_E$.
    Then ${\mathbf{N}}(E_{{\hspace{0.0pt}{\mathbin{{\hbox{\scalebox{0.7}{$\,\begin{picture}(-1,1)(-1,-2.5)\circle*{3}\end{picture}\,\,\, $}}}}}\hspace{+0pt}}{\hspace{-1pt}}}) = \ell^\infty(N,E)$ is the set of bounded sequences, $\mathbf{C}(E_{{\hspace{0.0pt}{\mathbin{{\hbox{\scalebox{0.7}{$\,\begin{picture}(-1,1)(-1,-2.5)\circle*{3}\end{picture}\,\,\, $}}}}}\hspace{+0pt}}{\hspace{-1pt}}},j)=c(N,E)$ is the set of all Cauchy sequences in $E$ and $\mathbf{C}_0(E_{{\hspace{0.0pt}{\mathbin{{\hbox{\scalebox{0.7}{$\,\begin{picture}(-1,1)(-1,-2.5)\circle*{3}\end{picture}\,\,\, $}}}}}\hspace{+0pt}}{\hspace{-1pt}}})=c_0(N,E)$ is the set of null sequences.
    Therefore, the above construction of the limit space $E_\infty=\mathbf{C}(E_{{\hspace{0.0pt}{\mathbin{{\hbox{\scalebox{0.7}{$\,\begin{picture}(-1,1)(-1,-2.5)\circle*{3}\end{picture}\,\,\, $}}}}}\hspace{+0pt}}{\hspace{-1pt}}},j)/\mathbf{C}_0(E_{{\hspace{0.0pt}{\mathbin{{\hbox{\scalebox{0.7}{$\,\begin{picture}(-1,1)(-1,-2.5)\circle*{3}\end{picture}\,\,\, $}}}}}\hspace{+0pt}}{\hspace{-1pt}}})$ amounts to Cauchy sequences modulo null sequences and we see that the limit space is the completion
    \begin{equation}
        E_\infty = \overline{E}.
    \end{equation}

\label{lem:subsystem limit}
    Let $(E,j)$ be a soft inductive system of normed spaces and let $N_0\subset N$ be cofinal.
    Then, the limit space of the subsystem over $N_0$ is isometrically isomorphic with $E_\infty$.

\label{cor:upropcont}
    Every contractive completely positive map $\varphi:\mathcal T_1\to\mathcal T_2$ that vanishes on ${\mathcal J}$, ${\mathcal J}\subset\ker(\varphi)$, factors through the quotient.
    That is, the map $\hat\varphi:\mathcal T_1/{\mathcal J}\to\mathcal T_2$ with $\hat\varphi(x+{\mathcal J}) = \varphi(x)$ is well-defined, contractive and completely positive.

\begin{enumerate}[(1)]
        \item\label{it:order_ideal}
            $\mathbf{C}_0(\mathcal S_{{\hspace{0.0pt}{\mathbin{{\hbox{\scalebox{0.7}{$\,\begin{picture}(-1,1)(-1,-2.5)\circle*{3}\end{picture}\,\,\, $}}}}}\hspace{+0pt}}{\hspace{-1pt}}})$ is a self-adjoint closed order ideal in $\mathbf{C}(\mathcal S_{{\hspace{0.0pt}{\mathbin{{\hbox{\scalebox{0.7}{$\,\begin{picture}(-1,1)(-1,-2.5)\circle*{3}\end{picture}\,\,\, $}}}}}\hspace{+0pt}}{\hspace{-1pt}}},j)$.
        \item\label{it:order_unit_norm}
            The order unit induced norm on the quotient $\mathbf{C}(\mathcal S_{{\hspace{0.0pt}{\mathbin{{\hbox{\scalebox{0.7}{$\,\begin{picture}(-1,1)(-1,-2.5)\circle*{3}\end{picture}\,\,\, $}}}}}\hspace{+0pt}}{\hspace{-1pt}}},j)/\mathbf{C}_0(\mathcal S_{{\hspace{0.0pt}{\mathbin{{\hbox{\scalebox{0.7}{$\,\begin{picture}(-1,1)(-1,-2.5)\circle*{3}\end{picture}\,\,\, $}}}}}\hspace{+0pt}}{\hspace{-1pt}}})$ coincides with the Banach space quotient norm, i.e.,
            \begin{equation}\label{eq:order_unit_norm}
                \inf_{b\in \mathbf{C}_0(\mathcal S_{{\hspace{0.0pt}{\mathbin{{\hbox{\scalebox{0.7}{$\,\begin{picture}(-1,1)(-1,-2.5)\circle*{3}\end{picture}\,\,\, $}}}}}\hspace{+0pt}}{\hspace{-1pt}}})} \norm{a_{{\hspace{0.0pt}{\mathbin{{\hbox{\scalebox{0.7}{$\,\begin{picture}(-1,1)(-1,-2.5)\circle*{3}\end{picture}\,\,\, $}}}}}\hspace{+0pt}}{\hspace{-1pt}}}+b_{{\hspace{0.0pt}{\mathbin{{\hbox{\scalebox{0.7}{$\,\begin{picture}(-1,1)(-1,-2.5)\circle*{3}\end{picture}\,\,\, $}}}}}\hspace{+0pt}}{\hspace{-1pt}}}}_{\mathbf{N}} =\inf \set{\lambda>0  \nonscript\ \delimsize\vert \allowbreak \nonscript\ \mathopen{}  \ensuremath{j_{}}\mkern-1mu\hbox{-}\mkern-3mu\IfNoValueTF{_}{\mathop{\textup{lim}}}{{_}\!-\!\mathop{\textup{lim}}}na_n\pm \lambda 1_\infty \in D_1} \quad \forall a_{{\hspace{0.0pt}{\mathbin{{\hbox{\scalebox{0.7}{$\,\begin{picture}(-1,1)(-1,-2.5)\circle*{3}\end{picture}\,\,\, $}}}}}\hspace{+0pt}}{\hspace{-1pt}}}=a_{{\hspace{0.0pt}{\mathbin{{\hbox{\scalebox{0.7}{$\,\begin{picture}(-1,1)(-1,-2.5)\circle*{3}\end{picture}\,\,\, $}}}}}\hspace{+0pt}}{\hspace{-1pt}}}^*\in\mathbf{C}(\mathcal S_{{\hspace{0.0pt}{\mathbin{{\hbox{\scalebox{0.7}{$\,\begin{picture}(-1,1)(-1,-2.5)\circle*{3}\end{picture}\,\,\, $}}}}}\hspace{+0pt}}{\hspace{-1pt}}},j).
            \end{equation}
        \item\label{it:kernel}
            $\mathbf{C}_0(\mathcal S_{{\hspace{0.0pt}{\mathbin{{\hbox{\scalebox{0.7}{$\,\begin{picture}(-1,1)(-1,-2.5)\circle*{3}\end{picture}\,\,\, $}}}}}\hspace{+0pt}}{\hspace{-1pt}}})$ is a kernel in the sense of \cite{kavruk2013quotients}.                                                                                            
    \end{enumerate}

\label{prop:jjconvlim}
    Let $(\mathcal S, j)$ and $(\mathcal T,k)$ be soft inductive systems of operator systems over the same directed set.
    Let $(\varphi_n:\mathcal S_n\to\mathcal T_n)_{n\in N}$ be a net of completely positive contractions taking \ensuremath{j_{}}-convergent to $k$-convergent nets.
    Then there is a completely positive contraction $\varphi_\infty:\mathcal S_\infty\to\mathcal T_\infty$ such that
    \begin{equation}
        \varphi_\infty\Big(\ensuremath{j_{}}\mkern-1mu\hbox{-}\mkern-3mu\IfNoValueTF{_}{\mathop{\textup{lim}}}{{_}\!-\!\mathop{\textup{lim}}}n a_n\Big) = k\mkern-1mu\hbox{-}\mkern-3mu\IfNoValueTF{_}{\mathop{\textup{lim}}}{{_}\!-\!\mathop{\textup{lim}}}n \varphi_n(a_n).
    \end{equation}

A {\bf soft inductive system of $\mathrm{C}^*$-algebras} over a directed set $(N,\le)$ is a soft inductive system of normed spaces $(\mathcal A,j)$ where each $\mathcal A_n$ is a $\mathrm{C}^*$-algebra and where the connecting $j_{nm}$ are ucp maps that are {\bf asymptotically multiplicative}
    \begin{equation}\label{eq:asymptotic_multiplicativity}
    \IfNoValueTF{_}{\mathop{\textup{lim}}}{{_}\!-\!\mathop{\textup{lim}}}{n\gg m}\,\norm{j_{nm}((j_{ml} a_l)(j_{ml} b_l))- (j_{nl} a_l)(j_{nl} b_l)} =0\quad\forall l\in N,\, a_l,b_l\in \mathcal A_l.
    \end{equation}

\label{prop:products}
    Let $(\mathcal A,j)$ be a soft inductive system of operator systems where each $\mathcal A_n$ is a $\mathrm{C}^*$-algebra.
    Consider the following statements:
    \begin{enumerate}[(a)]
        \item\label{it:products1}
            $n$-wise products of \ensuremath{j_{}}-convergent nets are \ensuremath{j_{}}-convergent.
        \item\label{it:products2}
            the connecting maps $\{j_{nm}\}$ are asymptotically multiplicative, see \eqref{eq:asymptotic_multiplicativity}. By definition, this means that $(\mathcal A,j)$ is a soft inductive system of $\mathrm{C}^*$-algebras.
        \item \label{it:products3}
            The limit space $\mathcal A_\infty$, naturally embedded into the quotient $\mathrm{C}^*$-algebra ${\mathbf{N}}(\mathcal A_{{\hspace{0.0pt}{\mathbin{{\hbox{\scalebox{0.7}{$\,\begin{picture}(-1,1)(-1,-2.5)\circle*{3}\end{picture}\,\,\, $}}}}}\hspace{+0pt}}{\hspace{-1pt}}})/\mathbf{C}_0(\mathcal A_{{\hspace{0.0pt}{\mathbin{{\hbox{\scalebox{0.7}{$\,\begin{picture}(-1,1)(-1,-2.5)\circle*{3}\end{picture}\,\,\, $}}}}}\hspace{+0pt}}{\hspace{-1pt}}})$, is closed under products.
    \end{enumerate}
    Then (a) $\iff$ (b) $\implies$ (c). If $(\mathcal A,j)$ is asymptotically isometric, then they're all equivalent.

We identify $\mathcal A_\infty$ with $\overline{ igcup_n j_{\infty n}(\mathcal A_n)}\subset {\mathbf Q}(\mathcal A_{{\hspace{0.0pt}{\mathbin{{\hbox{\scalebox{0.7}{$\, egin{picture}(-1,1)(-1,-2.5)\circle*{3}\end{picture}\,\,\, $}}}}}\hspace{+0pt}}{\hspace{-1pt}}})$. That $\mathcal A_\infty$ is nuclear follows from Ozawa and Sato's One-Way-CPAP (which can be found implicitly in \cite{Ozawa2002} (via \cite{KS03}); see \cite[Theorem 5.1]{Sato2019} for the explicit statement and proof) using the same argument as in \cite[Corollary 3.2]{C23} (which follows \cite[Theorem 2.13]{CW1}). ootnote{Even though the systems here are not necessarily strict, the map $\Phi$ from \cite[Corollary 3.2]{C23} is still just the inclusion of $\mathcal A_\infty$ into $\ell^\infty (N,\mathcal A_\infty)/c_0(N, \mathcal A_\infty)$ as constant sequences.} 

    Now, since $\mathcal A_\infty$ is nuclear, it has the local lifting property, which means in particular that for any finite-dimensional operator subsystem $\mathcal S$ of $\mathcal A$, there exists a ucp map $\psi_{\mathcal S}:\mathcal S	o {\mathbf{N}}(\mathcal A_{{\hspace{0.0pt}{\mathbin{{\hbox{\scalebox{0.7}{$\, egin{picture}(-1,1)(-1,-2.5)\circle*{3}\end{picture}\,\,\, $}}}}}\hspace{+0pt}}{\hspace{-1pt}}})$ so that $[\psi_{\mathcal S}(a)]=a$ for all $a\in \mathcal S$. Composing these with the projections ${\mathbf{N}}(\mathcal A_{{\hspace{0.0pt}{\mathbin{{\hbox{\scalebox{0.7}{$\, egin{picture}(-1,1)(-1,-2.5)\circle*{3}\end{picture}\,\,\, $}}}}}\hspace{+0pt}}{\hspace{-1pt}}})	o \mathcal A_n$, we obtain ucp maps $\psi_{\mathcal S,n}:\mathcal S	o \mathcal A_n\subset M_{
u(n)}$ (where $M_{
u(n)}$ is a full matrix algebra containing $\mathcal A_n$). By Arveson's extension theorem, these extend to ucp maps $\mathcal A	o \mathcal A_n\subset M_{
u(n)}$ which we also denote with $\psi_{\mathcal S,n}$. This gives us our desired net of pointwise asymptotically multiplicative and pointwise asymptotically isometric cpc maps.

Every unital nuclear $\mathrm{C}^*$-algebra $\mathcal A$ is a soft inductive limit of matrix algebras in the category of operator systems.
    This inductive system can be chosen to be split. 
    If $\mathcal A$ is separable, the directed set can be chosen to be $N=\mathbb N$.\footnote{In this case, the complete order isomorphism in the proof above is essentially the map $\Psi$ in \cite{CW1} and \cite{C23}.}

\label{prop:split nuc}
    Split inductive limits of nuclear operator systems are nuclear.
    In particular, split inductive limits of nuclear $\mathrm{C}^*$-algebras are nuclear.
